(function (root) {
  'use strict';

  const STATUSES = Object.freeze(['Draft','Data Inventory Needed','Privacy Review Needed','Ready for Review','Approved','Archived']);
  const STEPS = Object.freeze(['Data Purpose','Data Inventory','Sources and Permission','Data Classification','Collection and Consent','Access and Sharing','Storage and Retention','Quality and Fairness','Third-Party Services','Risks and Incident Response','Final Review']);
  const TEMPLATES = Object.freeze([
    {id:'learning',icon:'A+',title:'Student Learning Assistant',description:'Plan data for a student support tool with prompts, progress, privacy filters, and review.',exampleData:'Course, topic, learning goal, accessibility preference, prompt draft, AI response',privacy:'Minimize student identifiers and keep prompts private by default.'},
    {id:'research',icon:'SRC',title:'Research and Source Tool',description:'Track source records, verification notes, citations, and claim-evidence decisions.',exampleData:'Source title, URL, author, date, claim, evidence note, verification status',privacy:'Do not store private source accounts or personal browsing details.'},
    {id:'service',icon:'CS',title:'Community Service Platform',description:'Document tutoring or volunteer records with verifier review and limited sharing.',exampleData:'Service request, attendance record, tutor reflection, verifier decision',privacy:'Official service hours belong only to the student who completed them.'},
    {id:'accessibility',icon:'Aa',title:'Accessibility and Language Tool',description:'Plan language, speech, captions, reading supports, and low-bandwidth preferences.',exampleData:'Preferred language, reading level, TTS setting, caption setting, device capability',privacy:'Accessibility and disability-related information may be sensitive personal data.'},
    {id:'scratch',icon:'+',title:'Start from Scratch',description:'Build a custom data plan with no preset inventory.',exampleData:'Student-defined data only',privacy:'Start with the least data possible and add only what is necessary.'}
  ]);
  const DATA_CATEGORIES = Object.freeze(['Account information','Student content','Uploaded files','Voice recordings','Transcripts','Images','Course information','Learning progress','Accessibility settings','Language preferences','Device information','Usage analytics','Teacher feedback','Safety reports','AI prompts','AI responses','Verification records']);
  const SOURCE_STATUSES = Object.freeze(['Permission Confirmed','Publicly Available','Licence Review Needed','Consent Required','Restricted Use','Permission Unknown','Do Not Use']);
  const CLASSIFICATIONS = Object.freeze(['Public','Internal','Confidential','Sensitive Personal Data']);
  const SENSITIVE_CHECKS = Object.freeze(['Names','Student numbers','Contact information','Addresses','Location','Medical information','Disability information','Financial information','Immigration information','Academic records','Voice or image data','Safety reports','Information about minors','Authentication credentials']);
  const CONSENT_STATUSES = Object.freeze(['Not Required','Notice Required','Agreement Required','Guardian or School Process Required','Consent Collected','Consent Withdrawn','Needs Review']);
  const ACCESS_ROLES = Object.freeze(['Student','Team Member','Teacher','Parent or Guardian','Tutor','Verifier','Administrator','External Service','Public Viewer']);
  const ACCESS_PERMISSIONS = Object.freeze(['View','Create','Edit','Delete','Export','Share','Approve','No Access']);
  const LIFECYCLE = Object.freeze(['Collect','Use','Store','Share','Archive','Delete']);
  const QUALITY_STATUSES = Object.freeze(['Not Reviewed','Incomplete','Quality Concern','Representation Concern','Usable with Limitations','Reviewed','Needs Human Review']);
  const AI_FLOW = Object.freeze(['Student Input','Sensitive-Data Check','Redaction','AI Request','Output Validation','Student Response']);
  const SERVICES = Object.freeze(['AI provider','Cloud database','File storage','Translation','Speech-to-text','Text-to-speech','Analytics','Email','Calendar','Learning-management system']);
  const SERVICE_STATUSES = Object.freeze(['Not Reviewed','Reviewing','Approved for Prototype','Approved with Restrictions','Needs School Review','Do Not Use']);
  const RISK_CATEGORIES = Object.freeze(['Unauthorized access','Accidental sharing','Incorrect data','Data loss','Excessive collection','Sensitive AI prompts','Biased datasets','Third-party failure','Account misuse','Excessive retention','Failed deletion','Security breach']);
  const INCIDENT_FLOW = Object.freeze(['Issue Detected','Limit Access','Notify Reviewer','Investigate','Correct or Delete','Inform Affected Users When Required','Document Improvements']);
  const REVIEW_CHECKS = Object.freeze(['Data without purpose','Sensitive data without protection','Retention without justification','Missing deletion','Missing notice or consent','Unreviewed third parties','Unknown source permission','Personal data in AI prompts','Weak access controls','Missing human oversight','Representation concerns','Conflicts with System Card','Missing Architecture data flows']);
  const FINAL_FIELDS = Object.freeze(['Project Name','Data Purpose','Data Items','Data Sources','Permission','Classification','Collection and Notice','Access','Sharing','Storage','Retention','Deletion','AI Data Flow','Third-Party Services','Data Quality','Representation','Privacy Risks','Security Controls','Incident Response','Human Oversight','Open Questions','Version','Last Updated']);
  const DATA_MODELS = Object.freeze({
    DataResponsibilityPlan:['id','projectId','userId','title','purpose','status','currentStep','version','openRiskCount','submittedAt','approvedAt','createdAt','updatedAt'],
    ProjectDataAsset:['id','planId','name','description','category','purpose','required','provider','collectionPoint','storageLocation','classification','containsPersonalData','containsSensitiveData','retentionPeriod','deletionMethod','createdAt','updatedAt'],
    ProjectDataSource:['id','planId','name','sourceType','owner','acquisitionMethod','permissionStatus','licenceNotes','restrictions','verificationStatus','createdAt','updatedAt'],
    DataAccessRule:['id','planId','dataAssetId','role','canView','canCreate','canEdit','canDelete','canExport','canShare','canApprove','createdAt','updatedAt'],
    ThirdPartyDataService:['id','planId','serviceName','purpose','dataSent','dataReceived','retentionNotes','deletionSupport','privacyConcern','securityConcern','failureBehaviour','fallbackBehaviour','reviewStatus','createdAt','updatedAt'],
    ProjectDataRisk:['id','planId','dataAssetId','category','description','affectedUsers','likelihoodLevel','impactLevel','prevention','detectionMethod','responsePlan','responsibleRole','status','createdAt','updatedAt'],
    DataResponsibilityReview:['id','planId','reviewerId','status','feedback','requestedChanges','reviewedAt','createdAt','updatedAt'],
    DataResponsibilityVersion:['id','planId','version','changeSummary','assetsChanged','accessChanges','retentionChanges','serviceChanges','risksChanged','createdBy','createdAt']
  });

  const now=()=>new Date().toISOString();
  const uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
  const esc=value=>String(value==null?'':value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const accountId=()=>root.localStorage?.getItem('studyspark_session_v1')||'signed-out';
  const storageKey=()=>`studyspark_data_responsibility_plans_v1:${accountId()}`;
  let activeId=null, step=0, message='', loadError=false, sharePreview=false, noticePreview=false;

  function blankPlan(seed={}) {
    const stamp=now();
    return {
      id:uid('data-plan'),projectId:seed.projectId||uid('project'),userId:accountId(),title:seed.title||'',projectName:seed.projectName||'Selected Project',purpose:seed.purpose||'',status:'Draft',currentStep:0,version:'0.1',openRiskCount:0,submittedAt:null,approvedAt:null,createdAt:stamp,updatedAt:stamp,privateByDefault:true,
      projectPurpose:seed.projectPurpose||'',problemAddressed:seed.problemAddressed||'',intendedUsers:seed.intendedUsers||'',mainFunctions:seed.mainFunctions||'',reasonDataNeeded:seed.reasonDataNeeded||'',ifNotCollected:seed.ifNotCollected||'',requiredUses:'',optionalUses:'',unnecessaryUses:'',dataUseReviews:[],
      dataAssets:seed.dataAssets||[],sources:[],classificationNotes:'',sensitiveChecks:Object.fromEntries(SENSITIVE_CHECKS.map(name=>[name,'Not Checked'])),collectionNotice:'',consentStatus:'Needs Review',accessRules:[],selectedSharing:'',sharingExpiration:'',revocationProcess:'',sharingHistory:'',auditRecords:'',
      lifecycle:Object.fromEntries(LIFECYCLE.map(name=>[name,''])),qualityStatus:'Not Reviewed',qualityIssues:[],aiDataFlow:Object.fromEntries(AI_FLOW.map(name=>[name,{dataSent:'',dataRemoved:'',dataReceived:'',retention:'',trainingUse:'',validation:'',humanReview:'',fallback:''}])),privacyFilter:'',redactionPlan:'',outputValidation:'',humanOversight:'',
      services:[],risks:[],reviewIssues:[],reviews:[],versions:[],openQuestions:'',importsReviewed:seed.importsReviewed!==false,importedSources:seed.importedSources||[],languageMode:'English'
    };
  }
  function readAll(){try{const data=JSON.parse(root.localStorage?.getItem(storageKey())||'[]');loadError=false;return Array.isArray(data)?data.filter(item=>item&&item.userId===accountId()):[]}catch(_){loadError=true;return[]}}
  function writeAll(items){try{root.localStorage?.setItem(storageKey(),JSON.stringify(items));loadError=false;return true}catch(_){loadError=true;return false}}
  function getPlan(){return readAll().find(item=>item.id===activeId)||null}
  function savePlan(plan,notice='Draft saved'){const items=readAll(),index=items.findIndex(item=>item.id===plan.id);plan.userId=accountId();plan.updatedAt=now();plan.currentStep=Math.max(plan.currentStep||0,step);plan.openRiskCount=(plan.risks||[]).filter(risk=>risk.status!=='Resolved').length;if(index>=0)items[index]=plan;else items.unshift(plan);const saved=writeAll(items);message=saved?notice:'Unable to save data plan';return saved}
  function createPlan(seed={}){const plan=blankPlan(seed);plan.dataAssets.forEach(asset=>asset.planId=plan.id);activeId=plan.id;step=0;sharePreview=false;noticePreview=false;savePlan(plan,'Private data plan draft created');render()}
  function importRecord(kind){let seed={},sourceName=kind==='architecture'?'Architecture':'System Card';try{if(kind==='architecture'){const records=JSON.parse(root.localStorage?.getItem(`studyspark_project_architectures_v1:${accountId()}`)||'[]'),architecture=Array.isArray(records)?records[0]:null;if(architecture)seed={projectId:architecture.projectId,projectName:architecture.projectName,title:`${architecture.projectName||'Project'} Data Plan`,problemAddressed:architecture.problemAddressed,intendedUsers:architecture.intendedUsers,mainFunctions:architecture.requiredCapabilities,reasonDataNeeded:architecture.dataAccess,retention:architecture.retention,humanOversight:architecture.humanReviewRequirements||architecture.aiHumanReview,importedSources:['Architecture'],importsReviewed:false}}else{const records=JSON.parse(root.localStorage?.getItem(`studyspark_system_cards_v1:${accountId()}`)||'[]'),card=Array.isArray(records)?records[0]:null;if(card)seed={projectId:card.projectId,projectName:card.projectName,title:`${card.systemName||'Project'} Data Plan`,projectPurpose:card.problemAddressed,purpose:card.intendedUse||card.shortDescription,intendedUsers:card.primaryUsers,reasonDataNeeded:card.dataUsed,privacyFilter:card.privacyChecks,humanOversight:card.accountablePerson,importedSources:['System Card'],importsReviewed:false}}}catch(_){}createPlan(seed.title?seed:{title:`Imported ${sourceName} Data Plan`,projectName:'Selected Project',purpose:'Review imported fields before saving.',importedSources:[sourceName],importsReviewed:false});message=`${sourceName} imported. Review every field before saving.`;render()}
  function fromTemplate(template){if(readAll().length&&!root.confirm?.('Start a new data plan from this template? Your existing data plans will remain saved.'))return;const dataAssets=template.id==='scratch'?[]:template.exampleData.split(',').map((name,index)=>({id:uid('asset'),planId:'pending',name:name.trim(),description:'Review this suggested data item.',category:DATA_CATEGORIES[index%DATA_CATEGORIES.length],purpose:template.description,required:index<2?'Required':'Optional',provider:'Student or StudySpark',collectionPoint:'To be reviewed',storageLocation:'Private project workspace',accessRoles:'Student and authorized reviewer',externalSharing:'No external sharing until reviewed',classification:'Internal',containsPersonalData:/student|preference|voice|prompt|attendance/i.test(name),containsSensitiveData:/accessibility|voice|attendance/i.test(name),retentionPeriod:'Justify before collection',deletionMethod:'Delete all copies and derived records',createdAt:now(),updatedAt:now()}));createPlan({title:template.id==='scratch'?'':`${template.title} Data Plan`,purpose:template.description,reasonDataNeeded:template.exampleData,projectName:'Selected Project',dataAssets})}

  const field=(label,name,value,type='textarea',help='')=>`<label>${label}${type==='input'?`<input data-dr-field="${name}" value="${esc(value)}">`:`<textarea data-dr-field="${name}">${esc(value)}</textarea>`}${help?`<small>${help}</small>`:''}</label>`;
  const select=(label,name,value,options)=>`<label>${label}<select data-dr-field="${name}">${options.map(option=>`<option ${option===value?'selected':''}>${option}</option>`).join('')}</select></label>`;
  const val=id=>root.document.getElementById(id)?.value?.trim()||'';
  function summaryCounts(items){const plan=items[0]||{};return [
    ['Data Items Documented',plan.dataAssets?.length||0,'Data assets with a purpose, access, retention, and deletion plan.'],
    ['Sensitive Data Items',(plan.dataAssets||[]).filter(asset=>asset.containsSensitiveData||asset.classification==='Sensitive Personal Data').length,'Items requiring stronger protection and human review.'],
    ['Third-Party Services',plan.services?.length||0,'External services that receive or process project data.'],
    ['Open Data Risks',plan.openRiskCount||0,'Risks still needing prevention, response, or reviewer action.']
  ]}
  function header(){return root.ProjectToolHeader.render({pageClass:'dr-hero',titleId:'data-responsibility-title',backAttributes:{'data-dr-action':'projects'},backLabel:'Return to Projects',mainClass:'dr-hero-content',iconClass:'dr-hero-icon',icon:'DR',eyebrowClass:'dr-kicker dr-hero-eyebrow',eyebrow:'RESPONSIBLE PROJECT DATA',titleClass:'dr-hero-title',title:'Data Responsibility',descriptionClass:'dr-hero-description',description:'Plan what data your project needs, where it comes from, who can access it, how it is protected, and when it should be deleted.',projectContext:{className:'dr-project dr-hero-project',ariaLabel:'Current project',label:'Current Project',projectName:readAll()[0]?.projectName||'Choose or create a project',buttonAttributes:{'data-dr-action':'projects'}},guidanceClass:'dr-reminder dr-hero-reminder',guidance:'Collecting more data does not automatically make an AI system better. Use only the data the project genuinely needs.',actionsClass:'dr-hero-actions',actionsLabel:'Data Responsibility actions',actions:[{label:'Build My Data Plan',variant:'primary',attributes:{'data-dr-action':'start'}},{label:'Continue Draft',variant:'secondary',attributes:{'data-dr-action':'continue'}},{label:'Import from System Card',variant:'secondary',attributes:{'data-dr-action':'import-card'}},{label:'Import from Architecture',variant:'secondary',attributes:{'data-dr-action':'import-architecture'}},{label:'View an Example',variant:'tertiary',attributes:{'data-dr-action':'example'}}]})}
  function overview(){const items=readAll();return `${header()}${message?`<p class="dr-live" role="status">${esc(message)}</p>`:''}${summary(items)}${templates()}${emptyOrHistory(items)}`}
  function summary(items){if(!items.length)return'';const plan=items[0];return `<section class="dr-section" aria-labelledby="dr-summary"><div class="dr-section-head"><div><span class="dr-kicker">CURRENT DATA PLAN</span><h2 id="dr-summary">Data Responsibility Overview</h2></div><span class="dr-status"><span aria-hidden="true">●</span> ${esc(plan.status)}</span></div><div class="dr-summary-grid">${summaryCounts(items).map(([title,count,description],index)=>`<article><span aria-hidden="true">${['▦','◇','↗','!'][index]}</span><h3>${title}</h3><strong>${count}</strong><p>${description}</p></article>`).join('')}</div></section>`}
  function templates(){return `<section class="dr-section" aria-labelledby="dr-templates"><div class="dr-section-head"><div><span class="dr-kicker">QUICK START</span><h2 id="dr-templates">Data Responsibility Templates</h2><p>Templates create editable private drafts. They never overwrite saved data plans.</p></div></div><div class="dr-template-grid">${TEMPLATES.map(template=>`<article><span aria-hidden="true">${template.icon}</span><h3>${template.title}</h3><p>${template.description}</p><dl><div><dt>Example data</dt><dd>${template.exampleData}</dd></div><div><dt>Privacy consideration</dt><dd>${template.privacy}</dd></div></dl><button class="btn btn-secondary" data-dr-template="${template.id}" type="button">Start</button></article>`).join('')}</div></section>`}
  function emptyOrHistory(items){if(!items.length)return `<section class="dr-empty" aria-labelledby="dr-empty-title"><span aria-hidden="true">DR</span><h2 id="dr-empty-title">Plan how your project will handle data before collecting it. Identify what data is needed, remove what is unnecessary, and document access, protection, retention, and deletion.</h2><div><button class="btn btn-primary" data-dr-action="start" type="button">Build My First Data Plan</button><button class="btn btn-secondary" data-dr-action="import-card" type="button">Import from System Card</button><button class="btn btn-secondary" data-dr-action="templates" type="button">Use a Data Template</button><button class="btn btn-quiet" data-dr-action="example" type="button">View an Example</button></div></section>`;return `<section class="dr-section" aria-labelledby="dr-history"><div class="dr-section-head"><div><span class="dr-kicker">PRIVATE HISTORY</span><h2 id="dr-history">Data Plan History</h2></div></div><div class="dr-history-grid">${items.map(item=>`<article><div><span class="dr-status"><span aria-hidden="true">●</span> ${esc(item.status)}</span><h3>${esc(item.title||'Untitled Data Plan')}</h3><p>${esc(item.projectName)} · Version ${esc(item.version)}</p><small>${item.dataAssets.length} items · ${item.services.length} services · ${item.risks.length} risks</small></div><div class="dr-card-actions"><button class="btn btn-primary" data-dr-open="${item.id}" type="button">Continue Draft</button><button class="btn btn-secondary" data-dr-action="duplicate-plan" data-id="${item.id}" type="button">Duplicate</button><button class="btn btn-quiet" data-dr-action="export" data-id="${item.id}" type="button">Export</button><button class="btn btn-danger" data-dr-action="delete-plan" data-id="${item.id}" type="button">Delete Draft</button></div></article>`).join('')}</div></section>`}

  function sync(plan){if(!plan)return plan;root.document.querySelectorAll('#dataResponsibilityContent [data-dr-field]').forEach(control=>plan[control.dataset.drField]=control.value);SENSITIVE_CHECKS.forEach((name,index)=>{const value=plan[`sensitive_${index}`];if(value!==undefined)plan.sensitiveChecks[name]=value});AI_FLOW.forEach((name,index)=>{const stage=plan.aiDataFlow[name];['dataSent','dataRemoved','dataReceived','retention','trainingUse','validation','humanReview','fallback'].forEach(key=>{const value=plan[`ai_${index}_${key}`];if(value!==undefined)stage[key]=value})});LIFECYCLE.forEach((name,index)=>{const value=plan[`life_${index}`];if(value!==undefined)plan.lifecycle[name]=value});return plan}
  function stepPurpose(plan){return `<div class="dr-form-grid">${field('Data plan title','title',plan.title,'input')}${field('Selected project name','projectName',plan.projectName,'input')}${field('Project purpose','projectPurpose',plan.projectPurpose)}${field('Problem addressed','problemAddressed',plan.problemAddressed)}${field('Intended users','intendedUsers',plan.intendedUsers)}${field('Main functions','mainFunctions',plan.mainFunctions)}${field('Reason data is needed','reasonDataNeeded',plan.reasonDataNeeded)}${field('What happens if it is not collected','ifNotCollected',plan.ifNotCollected)}</div><div class="dr-requirements"><section><span class="dr-kicker">REQUIRED</span>${field('Required data uses','requiredUses',plan.requiredUses)}</section><section><span class="dr-kicker">OPTIONAL</span>${field('Optional data uses','optionalUses',plan.optionalUses)}</section><section><span class="dr-kicker">UNNECESSARY</span>${field('Unnecessary data uses','unnecessaryUses',plan.unnecessaryUses)}</section></div><section class="dr-guidance"><h3>For each proposed data use, ask:</h3><ul><li>Is it necessary?</li><li>Could less data be collected?</li><li>Could it be anonymous?</li><li>Could synthetic data be used?</li><li>Is permanent storage necessary?</li></ul></section>${plan.importedSources.length&&!plan.importsReviewed?`<div class="dr-notice" role="note"><strong>Imported from ${esc(plan.importedSources.join(' and '))}</strong><p>Review every imported field before using it in the final data plan.</p><button class="btn btn-secondary" data-dr-action="confirm-imports" type="button">I Reviewed the Imports</button></div>`:''}`}
  function assetForm(){return `<section class="dr-builder"><h3>Add Data Item</h3><div class="dr-form-grid compact"><label>Name<input id="dr-asset-name"></label><label>Category<select id="dr-asset-category">${DATA_CATEGORIES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Description<textarea id="dr-asset-description"></textarea></label><label>Purpose<textarea id="dr-asset-purpose"></textarea></label><label>Required or optional<select id="dr-asset-required"><option>Required</option><option>Optional</option><option>Unnecessary</option></select></label><label>Provider<input id="dr-asset-provider"></label><label>Collection point<input id="dr-asset-collection"></label><label>Storage location<input id="dr-asset-storage"></label><label>Access roles<input id="dr-asset-access"></label><label>External sharing<input id="dr-asset-sharing"></label><label>Retention<input id="dr-asset-retention"></label><label>Deletion method<input id="dr-asset-deletion"></label></div><button class="btn btn-primary" data-dr-action="add-asset" type="button">Add Data Item</button></section>`}
  function stepInventory(plan){return `${assetForm()}<section class="dr-card-list" aria-labelledby="dr-items"><h3 id="dr-items">Documented Data Items</h3>${plan.dataAssets.length?plan.dataAssets.map(asset=>`<details><summary><span>${esc(asset.name)}</span><span class="dr-status"><span aria-hidden="true">●</span> ${esc(asset.required)}</span></summary><dl><div><dt>Description</dt><dd>${esc(asset.description)}</dd></div><div><dt>Purpose</dt><dd>${esc(asset.purpose)}</dd></div><div><dt>Category</dt><dd>${esc(asset.category)}</dd></div><div><dt>Provider</dt><dd>${esc(asset.provider)}</dd></div><div><dt>Storage</dt><dd>${esc(asset.storageLocation)}</dd></div><div><dt>Retention</dt><dd>${esc(asset.retentionPeriod)}</dd></div><div><dt>Deletion</dt><dd>${esc(asset.deletionMethod)}</dd></div></dl></details>`).join(''):'<p class="dr-inline-empty">No data items documented yet.</p>'}</section>`}
  function stepSources(plan){return `<section class="dr-builder"><h3>Add Data Source</h3><div class="dr-form-grid compact"><label>Name<input id="dr-source-name"></label><label>Type<input id="dr-source-type"></label><label>Owner<input id="dr-source-owner"></label><label>Acquisition method<input id="dr-source-method"></label><label>Permission<select id="dr-source-permission">${SOURCE_STATUSES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Licence or terms<textarea id="dr-source-licence"></textarea></label><label>Date received<input id="dr-source-date" type="date"></label><label>Restrictions<textarea id="dr-source-restrictions"></textarea></label><label>Responsible role<input id="dr-source-role"></label><label>Verification status<input id="dr-source-verification"></label></div><button class="btn btn-primary" data-dr-action="add-source" type="button">Add Source</button></section>${plan.sources.some(source=>['Permission Unknown','Licence Review Needed','Consent Required','Restricted Use','Do Not Use'].includes(source.permissionStatus))?'<p class="dr-warning" role="alert">Source ownership or permission is unclear. Do not use restricted or unknown sources until reviewed.</p>':''}<div class="dr-record-list">${plan.sources.map(source=>`<article><span class="dr-status"><span aria-hidden="true">●</span> ${esc(source.permissionStatus)}</span><h3>${esc(source.name)}</h3><p>${esc(source.owner)} · ${esc(source.sourceType)}</p><small>${esc(source.restrictions||'No restrictions documented')}</small></article>`).join('')||'<p class="dr-inline-empty">No sources documented yet.</p>'}</div>`}
  function stepClassification(plan){return `<div class="dr-form-grid">${select('Overall consent or notice status','consentStatus',plan.consentStatus,CONSENT_STATUSES)}${field('Classification notes','classificationNotes',plan.classificationNotes)}${field('Plain-language notice builder','collectionNotice',plan.collectionNotice,'textarea','A checkbox alone does not prove legal compliance.')}</div><section class="dr-checks"><h3>Sensitive Data Check</h3>${SENSITIVE_CHECKS.map((name,index)=>`<label><span>${name}</span><select data-dr-field="sensitive_${index}"><option ${plan.sensitiveChecks[name]==='Not Checked'?'selected':''}>Not Checked</option><option ${plan.sensitiveChecks[name]==='Not Present'?'selected':''}>Not Present</option><option ${plan.sensitiveChecks[name]==='Present'?'selected':''}>Present</option><option ${plan.sensitiveChecks[name]==='Do Not Store'?'selected':''}>Do Not Store</option></select></label>`).join('')}<p class="dr-warning">Passwords, API keys, and access tokens must never be stored in the project plan.</p></section><div class="dr-flow-labels">${CLASSIFICATIONS.map(x=>`<span>${x}</span>`).join('')}</div>`}
  function stepConsent(plan){return `<div class="dr-form-grid">${field('What is collected','collectionWhat',plan.collectionWhat||'')}${field('Why it is collected','collectionWhy',plan.collectionWhy||'')}${field('Whether optional','collectionOptional',plan.collectionOptional||'')}${field('How it is used','collectionUse',plan.collectionUse||'')}${field('Who can access it','collectionAccess',plan.collectionAccess||'')}${field('Whether sent to an AI provider','collectionAIProvider',plan.collectionAIProvider||'')}${field('Retention','collectionRetention',plan.collectionRetention||'')}${field('Removal process','collectionRemoval',plan.collectionRemoval||'')}</div><section class="dr-notice-preview"><h3>Plain-Language Notice</h3><p>${esc(plan.collectionNotice||'Describe what is collected, why, who can access it, whether it is optional, and how it can be removed.')}</p><button class="btn btn-secondary" data-dr-action="preview-notice" type="button">Preview Notice</button></section>${noticePreview?'<section class="dr-share-preview"><h3>Notice Preview</h3><p>This preview is for review only and does not collect consent or prove compliance.</p></section>':''}`}
  function stepAccess(plan){return `<div class="dr-form-grid">${field('Selected sharing','selectedSharing',plan.selectedSharing)}${field('Expiration dates','sharingExpiration',plan.sharingExpiration,'input')}${field('Revocation process','revocationProcess',plan.revocationProcess)}${field('Sharing history','sharingHistory',plan.sharingHistory)}${field('Audit records','auditRecords',plan.auditRecords)}</div><section class="dr-access-matrix"><h3>Role-Access Matrix</h3><div>${ACCESS_ROLES.map(role=>`<article><h4>${role}</h4>${ACCESS_PERMISSIONS.map(permission=>`<label><input type="checkbox" data-dr-access="${role}:${permission}"> ${permission}</label>`).join('')}</article>`).join('')}</div><p>Final access must be enforced by server-side authorization, not by hiding buttons.</p></section>`}
  function stepLifecycle(plan){return `<section class="dr-lifecycle"><h3>Data Lifecycle</h3><div>${LIFECYCLE.map(x=>`<span>${x}</span>`).join('<b aria-hidden="true">→</b>')}</div></section><div class="dr-form-grid">${LIFECYCLE.map((name,index)=>field(`${name} plan`,`life_${index}`,plan.lifecycle[name])).join('')}${field('Justify every retention period','retentionJustification',plan.retentionJustification||'')}</div>`}
  function stepQuality(plan){return `<div class="dr-form-grid">${select('Quality review status','qualityStatus',plan.qualityStatus,QUALITY_STATUSES)}${field('Who is represented?','represented',plan.represented||'')}${field('Who may be missing?','missingRepresentation',plan.missingRepresentation||'')}${field('Can users correct errors?','correctionPath',plan.correctionPath||'')}${field('Language representation','languageRepresentation',plan.languageRepresentation||'')}${field('Remaining limitation','remainingLimitation',plan.remainingLimitation||'')}</div><section class="dr-builder"><h3>Add Quality or Fairness Issue</h3><div class="dr-form-grid compact"><label>Problem<textarea id="dr-quality-problem"></textarea></label><label>People affected<textarea id="dr-quality-people"></textarea></label><label>Evidence<textarea id="dr-quality-evidence"></textarea></label><label>Impact<textarea id="dr-quality-impact"></textarea></label><label>Mitigation<textarea id="dr-quality-mitigation"></textarea></label><label>Remaining limitation<textarea id="dr-quality-limitation"></textarea></label></div><button class="btn btn-primary" data-dr-action="add-quality" type="button">Add Issue</button></section>${recordList(plan.qualityIssues,'Quality and Representation Issues','problem','impact')}`}
  function stepAI(plan){return `<section class="dr-ai-flow"><h3>AI Data Flow</h3><div>${AI_FLOW.map(x=>`<span>${x}</span>`).join('<b aria-hidden="true">→</b>')}</div></section><ol class="dr-mobile-flow">${AI_FLOW.map(x=>`<li>${x}</li>`).join('')}</ol><div class="dr-ai-stages">${AI_FLOW.map((name,index)=>{const stage=plan.aiDataFlow[name];return `<details><summary>${index+1}. ${name}</summary><div class="dr-form-grid compact">${['dataSent','dataRemoved','dataReceived','retention','trainingUse','validation','humanReview','fallback'].map(key=>field(key.replace(/[A-Z]/g,m=>` ${m.toLowerCase()}`),`ai_${index}_${key}`,stage[key])).join('')}</div></details>`}).join('')}</div><div class="dr-form-grid">${field('Privacy filter','privacyFilter',plan.privacyFilter)}${field('Redaction','redactionPlan',plan.redactionPlan)}${field('Output validation','outputValidation',plan.outputValidation)}${field('Human review','humanOversight',plan.humanOversight)}</div><p class="dr-warning">Never store secret values, passwords, tokens, or API keys.</p>`}
  function stepServices(plan){return `${stepAI(plan)}<section class="dr-builder"><h3>Add Third-Party Service</h3><div class="dr-form-grid compact"><label>Name<select id="dr-service-name">${SERVICES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Purpose<textarea id="dr-service-purpose"></textarea></label><label>Data sent<textarea id="dr-service-sent"></textarea></label><label>Data received<textarea id="dr-service-received"></textarea></label><label>Contract owner<input id="dr-service-owner"></label><label>Retention<textarea id="dr-service-retention"></textarea></label><label>Deletion support<textarea id="dr-service-deletion"></textarea></label><label>Security concern<textarea id="dr-service-security"></textarea></label><label>Privacy concern<textarea id="dr-service-privacy"></textarea></label><label>Failure behaviour<textarea id="dr-service-failure"></textarea></label><label>Fallback<textarea id="dr-service-fallback"></textarea></label><label>Review status<select id="dr-service-status">${SERVICE_STATUSES.map(x=>`<option>${x}</option>`).join('')}</select></label></div><button class="btn btn-primary" data-dr-action="add-service" type="button">Add Service</button></section>${recordList(plan.services,'Third-Party Services','serviceName','reviewStatus')}`}
  function stepRisks(plan){return `<section class="dr-incident"><h3>Incident Flow</h3><div>${INCIDENT_FLOW.map(x=>`<span>${x}</span>`).join('<b aria-hidden="true">→</b>')}</div></section><section class="dr-builder"><h3>Add Data Risk</h3><div class="dr-form-grid compact"><label>Category<select id="dr-risk-category">${RISK_CATEGORIES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Description<textarea id="dr-risk-description"></textarea></label><label>Data affected<textarea id="dr-risk-data"></textarea></label><label>Users affected<textarea id="dr-risk-users"></textarea></label><label>Likelihood<input id="dr-risk-likelihood"></label><label>Impact<input id="dr-risk-impact"></label><label>Prevention<textarea id="dr-risk-prevention"></textarea></label><label>Detection<textarea id="dr-risk-detection"></textarea></label><label>Immediate response<textarea id="dr-risk-response"></textarea></label><label>Responsible role<input id="dr-risk-role"></label><label>Notification<textarea id="dr-risk-notification"></textarea></label><label>Recovery<textarea id="dr-risk-recovery"></textarea></label></div><button class="btn btn-primary" data-dr-action="add-risk" type="button">Add Risk</button></section>${recordList(plan.risks,'Risks and Responses','category','status')}`}
  function finalRows(plan){return FINAL_FIELDS.map(label=>{const value={ 'Project Name':plan.projectName,'Data Purpose':plan.projectPurpose||plan.purpose,'Data Items':`${plan.dataAssets.length} documented`,'Data Sources':`${plan.sources.length} documented`,Permission:plan.sources.map(x=>x.permissionStatus).join(', '),Classification:plan.classificationNotes,'Collection and Notice':plan.collectionNotice,Access:plan.collectionAccess||plan.selectedSharing,Sharing:plan.selectedSharing,Storage:plan.dataAssets.map(x=>x.storageLocation).filter(Boolean).join('; '),Retention:plan.retentionJustification||plan.collectionRetention,Deletion:plan.collectionRemoval||plan.lifecycle.Delete,'AI Data Flow':AI_FLOW.join(' -> '),'Third-Party Services':`${plan.services.length} documented`,'Data Quality':plan.qualityStatus,Representation:plan.represented||plan.missingRepresentation,'Privacy Risks':`${plan.risks.length} documented`,'Security Controls':plan.privacyFilter||plan.redactionPlan,'Incident Response':INCIDENT_FLOW.join(' -> '),'Human Oversight':plan.humanOversight,'Open Questions':plan.openQuestions,Version:plan.version,'Last Updated':new Date(plan.updatedAt).toLocaleDateString()}[label];return [label,value]})}
  function stepReview(plan){return `<div class="dr-review-head"><button class="btn btn-primary" data-dr-action="review" type="button">Review My Data Plan</button><p>This check identifies issues and never modifies the plan automatically.</p></div><section class="dr-checks"><h3>Review Checks</h3><ul>${REVIEW_CHECKS.map(label=>`<li><span aria-hidden="true">✓</span>${label}</li>`).join('')}</ul></section>${plan.reviewIssues.length?`<section class="dr-issues"><h3>Data Plan Review Issues</h3>${plan.reviewIssues.map(issue=>`<article><span class="dr-status"><span aria-hidden="true">!</span> ${esc(issue.status)}</span><h4>${esc(issue.issue)}</h4><p><strong>Why it matters:</strong> ${esc(issue.whyItMatters)}</p><p><strong>Affected data:</strong> ${esc(issue.affectedData)}</p><p><strong>Suggested improvement:</strong> ${esc(issue.suggestedImprovement)}</p><button class="btn btn-secondary" data-dr-action="resolve-issue" data-id="${issue.id}" type="button">Mark Addressed</button></article>`).join('')}</section>`:''}<article class="dr-final"><div><span class="dr-kicker">FINAL DATA RESPONSIBILITY PLAN</span><h2>${esc(plan.title||'Untitled Data Plan')}</h2><span class="dr-status"><span aria-hidden="true">●</span> ${esc(plan.status)}</span></div><dl>${finalRows(plan).map(([name,value])=>`<div><dt>${name}</dt><dd>${value?esc(value):'Not documented yet.'}</dd></div>`).join('')}</dl></article><div class="dr-form-grid">${field('Open questions','openQuestions',plan.openQuestions)}</div>${sharePreview?'<section class="dr-share-preview"><h3>Export Preview</h3><p>Draft evidence, private AI chats, personal details, confidential notes, and unselected sensitive data are excluded. Nothing has been shared.</p><button class="btn btn-secondary" data-dr-action="close-preview" type="button">Close Preview</button></section>':''}<div class="dr-final-actions"><button class="btn btn-secondary" data-dr-action="edit" type="button">Edit Plan</button><button class="btn btn-secondary" data-dr-action="save" type="button">Save Draft</button><button class="btn btn-primary" data-dr-action="submit" type="button">Request Teacher Review</button><button class="btn btn-secondary" data-dr-action="preview" type="button">Export Data Plan</button><button class="btn btn-primary" data-dr-action="testing" type="button">Continue to Testing</button></div><section class="dr-version-history"><h3>Version History and Review</h3>${plan.versions.length?`<ol>${plan.versions.map(version=>`<li><strong>Version ${esc(version.version)}</strong> · ${new Date(version.createdAt).toLocaleDateString()} · ${esc(version.createdBy)}<p>${esc(version.changeSummary)}</p><small>Assets: ${esc(version.assetsChanged)} · Access: ${esc(version.accessChanges)} · Retention: ${esc(version.retentionChanges)} · Services: ${esc(version.serviceChanges)} · Risks: ${esc(version.risksChanged)}</small></li>`).join('')}</ol>`:'<p>No preserved versions yet.</p>'}<button class="btn btn-secondary" data-dr-action="version" type="button">Preserve Current Version</button><p>Human approval is required for Approved status.</p></section>`}
  const renderStep=plan=>[stepPurpose,stepInventory,stepSources,stepClassification,stepConsent,stepAccess,stepLifecycle,stepQuality,stepServices,stepRisks,stepReview][step](plan);
  function wizard(plan){return `<header class="dr-workspace-head"><button class="study-page-back" data-dr-action="overview" type="button" aria-label="Return to Data Responsibility overview"><span aria-hidden="true">←</span></button><div><span class="dr-kicker">PRIVATE DATA PLAN</span><h1>Data Responsibility</h1><p>${esc(plan.projectName)} · ${esc(plan.status)}</p></div><div class="dr-access-actions"><label>Description language<select data-dr-field="languageMode"><option ${plan.languageMode==='English'?'selected':''}>English</option><option ${plan.languageMode==='Bilingual'?'selected':''}>Bilingual</option></select></label><button class="btn btn-quiet" data-dr-action="listen" type="button">Listen</button><button class="btn btn-quiet" data-dr-action="speech" type="button">Speech-to-Text</button></div></header><nav class="dr-stepper" aria-label="Data Responsibility steps"><ol>${STEPS.map((name,index)=>`<li ${index===step?'aria-current="step"':''}><button data-dr-step="${index}" type="button"><span>${index+1}</span>${name}</button></li>`).join('')}</ol></nav><section class="dr-wizard" aria-labelledby="dr-current-step"><div class="dr-progress"><div><span>Step ${step+1} of 11 — ${STEPS[step]}</span><strong id="dr-current-step">${STEPS[step]}</strong></div><progress max="11" value="${step+1}">${step+1} of 11</progress></div>${message?`<p class="dr-live" role="status">${esc(message)}</p>`:''}<div class="dr-step-content">${renderStep(plan)}</div><footer class="dr-wizard-actions"><button class="btn btn-secondary" data-dr-action="save" type="button">Save Draft</button><button class="btn btn-quiet" data-dr-action="overview" type="button">Exit and Return Later</button><span></span><button class="btn btn-secondary" data-dr-action="back" type="button" ${step===0?'disabled':''}>Back</button><button class="btn btn-primary" data-dr-action="next" type="button">${step===10?'Review Plan':'Continue'}</button></footer></section>`}
  function recordList(records,title,primary,secondary){return `<section class="dr-record-list-wrap"><h3>${title}</h3><div class="dr-record-list">${records.map(record=>`<article><span class="dr-status"><span aria-hidden="true">●</span> ${esc(record[secondary]||record.status||'Draft')}</span><h4>${esc(record[primary]||record.name||'Untitled')}</h4><p>${esc(record.description||record.purpose||record.affectedUsers||'Review details before finalizing.')}</p></article>`).join('')||'<p class="dr-inline-empty">Nothing documented yet.</p>'}</div></section>`}
  function reviewIssues(plan){const issues=[];const add=(issue,why,affected,suggestion)=>issues.push({id:uid('issue'),issue,whyItMatters:why,affectedData:affected,suggestedImprovement:suggestion,status:'Open',createdAt:now()});if(!plan.projectPurpose&&!plan.purpose)add('Data without purpose','A project should not collect data until its learning purpose is clear.','All proposed data','Explain the project purpose and why data is needed.');if(!plan.dataAssets.length)add('Data Inventory Needed','Students and reviewers need to know exactly what data is collected.','Project data inventory','Add each data item as an expandable inventory card.');plan.dataAssets.forEach(asset=>{if((asset.containsSensitiveData||asset.classification==='Sensitive Personal Data')&&!asset.storageLocation)add('Sensitive data without protection','Sensitive data needs clear storage and protection before collection.',asset.name,'Add storage, access, and protection details.');if(!asset.retentionPeriod)add('Retention without justification','Keeping data longer than needed increases risk.',asset.name,'Add a justified retention period.');if(!asset.deletionMethod)add('Missing deletion','Students need to know how every copy can be removed.',asset.name,'Document deletion for original and derived copies.')});if(plan.sources.some(source=>['Permission Unknown','Licence Review Needed','Consent Required','Restricted Use','Do Not Use'].includes(source.permissionStatus)))add('Unknown source permission','Unclear permission can make project use unsafe or unauthorized.','Data sources','Confirm permission, licence, consent, or mark the source Do Not Use.');if(['Needs Review','Notice Required','Agreement Required','Guardian or School Process Required'].includes(plan.consentStatus)&&!plan.collectionNotice)add('Missing notice or consent','People should understand what is collected and how it is used.','Collection notice','Write a plain-language notice and identify the required process.');if(plan.services.some(service=>['Not Reviewed','Reviewing','Needs School Review','Do Not Use'].includes(service.reviewStatus)))add('Unreviewed third parties','External services may store, train on, or fail to delete project data.','Third-party services','Review each service and document fallback and deletion support.');if(/student|name|number|address|phone|medical|financial|immigration/i.test(plan.reasonDataNeeded||'')&&!plan.redactionPlan)add('Personal data in AI prompts','AI requests should be minimized and redacted before sending.','AI data flow','Add a sensitive-data check and redaction plan.');if(!plan.selectedSharing&&!plan.auditRecords)add('Weak access controls','Hiding interface controls is not the same as authorization.','Access and sharing','Document server-side authorization, sharing, revocation, and audit records.');if(!plan.humanOversight)add('Missing human oversight','AI and automated checks cannot approve a data plan.','Review process','Name the authorized reviewer or human-review process.');if(plan.qualityStatus!=='Reviewed'&&!plan.qualityIssues.length)add('Representation concerns','Missing or low-quality data can create unequal outcomes.','Quality and fairness','Review who is represented, who is missing, and remaining limitations.');if(plan.importedSources.includes('System Card')&&!plan.importsReviewed)add('Conflicts with System Card','Imported fields must be reviewed before they become project commitments.','System Card import','Review and confirm imported System Card details.');if(plan.importedSources.includes('Architecture')&&!Object.values(plan.aiDataFlow).some(stage=>stage.dataSent||stage.dataReceived))add('Missing Architecture data flows','The Data Plan should match the project architecture.','Architecture import','Document the actual data sent, removed, received, and validated.');return issues}
  function preserveVersion(plan){plan.versions.push({id:uid('data-version'),planId:plan.id,version:plan.version,changeSummary:'Student preserved the current data responsibility plan.',assetsChanged:`${plan.dataAssets.length} data items documented`,accessChanges:plan.selectedSharing||'No sharing changes recorded',retentionChanges:plan.retentionJustification||'No retention change recorded',serviceChanges:`${plan.services.length} third-party services documented`,risksChanged:`${plan.risks.length} risks documented`,createdBy:accountId(),createdAt:now()})}
  function exportPlan(plan){const blob=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),link=root.document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${(plan.title||'data-responsibility-plan').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`;link.click();URL.revokeObjectURL(link.href)}
  function addRecord(collection,record,notice){const plan=sync(getPlan());if(!plan)return;plan[collection].push({id:uid(collection),planId:plan.id,createdAt:now(),updatedAt:now(),status:'Draft',...record});savePlan(plan,notice);render()}
  function handle(action,id){const items=readAll();let plan=getPlan();if(action==='retry')return retry();if(action==='projects')return root.showView?.('communityAIProject');if(action==='start')return createPlan();if(action==='continue'){const draft=items.find(x=>!['Approved','Archived'].includes(x.status))||items[0];return draft?(activeId=draft.id,step=Math.min(draft.currentStep||0,10),message='Draft restored',render()):createPlan()}if(action==='import-card')return importRecord('card');if(action==='import-architecture')return importRecord('architecture');if(action==='example')return fromTemplate(TEMPLATES[0]);if(action==='templates'){message='Choose a template above. Saved data plans will not be overwritten.';return render()}if(action==='overview'){if(plan)savePlan(sync(plan),'Draft saved');activeId=null;message='';return render()}if(action==='save'&&plan){savePlan(sync(plan),'Draft saved');return render()}if(action==='back'&&plan){savePlan(sync(plan),'Draft saved');step=Math.max(0,step-1);return render()}if(action==='next'&&plan){savePlan(sync(plan),'Draft saved');step=Math.min(10,step+1);return render()}if(action==='edit'){step=0;return render()}if(action==='confirm-imports'&&plan){plan.importsReviewed=true;savePlan(sync(plan),'Imported details reviewed');return render()}if(action==='add-asset')return addRecord('dataAssets',{name:val('dr-asset-name')||'Untitled data item',description:val('dr-asset-description'),category:val('dr-asset-category'),purpose:val('dr-asset-purpose'),required:val('dr-asset-required'),provider:val('dr-asset-provider'),collectionPoint:val('dr-asset-collection'),storageLocation:val('dr-asset-storage'),accessRoles:val('dr-asset-access'),externalSharing:val('dr-asset-sharing'),retentionPeriod:val('dr-asset-retention'),deletionMethod:val('dr-asset-deletion'),classification:'Internal',containsPersonalData:/student|name|number|address|phone|voice|image/i.test(`${val('dr-asset-name')} ${val('dr-asset-description')}`),containsSensitiveData:/medical|disability|financial|immigration|safety|password|token|api key/i.test(`${val('dr-asset-name')} ${val('dr-asset-description')}`)},'Data item added');if(action==='add-source')return addRecord('sources',{name:val('dr-source-name')||'Untitled source',sourceType:val('dr-source-type'),owner:val('dr-source-owner'),acquisitionMethod:val('dr-source-method'),permissionStatus:val('dr-source-permission'),licenceNotes:val('dr-source-licence'),dateReceived:val('dr-source-date'),restrictions:val('dr-source-restrictions'),responsibleRole:val('dr-source-role'),verificationStatus:val('dr-source-verification')},'Source added');if(action==='add-quality')return addRecord('qualityIssues',{problem:val('dr-quality-problem')||'Quality issue needs a description',peopleAffected:val('dr-quality-people'),evidence:val('dr-quality-evidence'),impact:val('dr-quality-impact'),mitigation:val('dr-quality-mitigation'),remainingLimitation:val('dr-quality-limitation')},'Quality issue added');if(action==='add-service')return addRecord('services',{serviceName:val('dr-service-name'),purpose:val('dr-service-purpose'),dataSent:val('dr-service-sent'),dataReceived:val('dr-service-received'),contractOwner:val('dr-service-owner'),retentionNotes:val('dr-service-retention'),deletionSupport:val('dr-service-deletion'),securityConcern:val('dr-service-security'),privacyConcern:val('dr-service-privacy'),failureBehaviour:val('dr-service-failure'),fallbackBehaviour:val('dr-service-fallback'),reviewStatus:val('dr-service-status')},'Third-party service added');if(action==='add-risk')return addRecord('risks',{category:val('dr-risk-category'),description:val('dr-risk-description')||'Risk needs a description',dataAffected:val('dr-risk-data'),affectedUsers:val('dr-risk-users'),likelihoodLevel:val('dr-risk-likelihood'),impactLevel:val('dr-risk-impact'),prevention:val('dr-risk-prevention'),detectionMethod:val('dr-risk-detection'),responsePlan:val('dr-risk-response'),responsibleRole:val('dr-risk-role'),notification:val('dr-risk-notification'),recovery:val('dr-risk-recovery'),status:'Open'},'Risk added');if(action==='review'&&plan){sync(plan);plan.reviewIssues=reviewIssues(plan);plan.status=plan.reviewIssues.length?'Privacy Review Needed':'Ready for Review';savePlan(plan,plan.reviewIssues.length?'Data plan review found issues':'Data plan is ready for human review');return render()}if(action==='resolve-issue'&&plan){const issue=plan.reviewIssues.find(x=>x.id===id);if(issue)issue.status='Addressed';savePlan(plan,'Issue marked addressed. Review again to confirm.');return render()}if(action==='version'&&plan){sync(plan);preserveVersion(plan);savePlan(plan,'Current data plan version preserved');return render()}if(action==='submit'&&plan){sync(plan);const open=reviewIssues(plan);if(open.length){plan.reviewIssues=open;plan.status='Privacy Review Needed';savePlan(plan,'Resolve data responsibility issues before requesting review');return render()}plan.status='Ready for Review';plan.submittedAt=now();preserveVersion(plan);savePlan(plan,'Data plan submitted for authorized human review');return render()}if(action==='preview'&&plan){sharePreview=true;message='Review the export preview. Nothing has been shared.';return render()}if(action==='close-preview'){sharePreview=false;return render()}if(action==='preview-notice'){noticePreview=true;return render()}if(action==='testing')return root.showView?.('communityAIProject');if(action==='listen'){const text=root.document.querySelector('#dataResponsibilityContent .dr-step-content')?.innerText||'';if(root.speechSynthesis&&root.SpeechSynthesisUtterance){root.speechSynthesis.cancel();root.speechSynthesis.speak(new SpeechSynthesisUtterance(text))}else{message='Listening is not available in this browser.';render()}return}if(action==='speech'){const Recognition=root.SpeechRecognition||root.webkitSpeechRecognition,target=root.document.activeElement;if(!Recognition||!target||!['INPUT','TEXTAREA'].includes(target.tagName)){message='Select a text field first. Speech-to-Text is not available in every browser.';return render()}const recognition=new Recognition();recognition.onresult=event=>{target.value=`${target.value} ${event.results[0][0].transcript}`.trim();target.dispatchEvent(new Event('input',{bubbles:true}))};recognition.start();return}if(action==='duplicate-plan'){const original=items.find(x=>x.id===id);if(!original)return;const copy=JSON.parse(JSON.stringify(original));copy.id=uid('data-plan');copy.title=`${copy.title||'Untitled Data Plan'} - Copy`;copy.status='Draft';copy.versions=[];copy.reviews=[];copy.submittedAt=copy.approvedAt=null;copy.createdAt=copy.updatedAt=now();items.unshift(copy);writeAll(items);message='Data plan duplicated';return render()}if(action==='delete-plan'){const original=items.find(x=>x.id===id);if(!original||original.status==='Approved'){message='Approved data plan versions are preserved.';return render()}if(root.confirm?.('Delete this private data plan draft?')){writeAll(items.filter(x=>x.id!==id));message='Draft deleted';render()}return}if(action==='export'){const original=items.find(x=>x.id===id)||plan;if(original)exportPlan(original)}}
  function bind(){const host=root.document.getElementById('dataResponsibilityContent');host?.querySelectorAll('[data-dr-template]').forEach(button=>button.addEventListener('click',()=>fromTemplate(TEMPLATES.find(item=>item.id===button.dataset.drTemplate))));host?.querySelectorAll('[data-dr-open]').forEach(button=>button.addEventListener('click',()=>{activeId=button.dataset.drOpen;const plan=getPlan();step=Math.min(plan?.currentStep||0,10);message='Draft restored';render()}));host?.querySelectorAll('[data-dr-step]').forEach(button=>button.addEventListener('click',()=>{const plan=sync(getPlan());savePlan(plan,'Draft saved');step=Number(button.dataset.drStep);render()}));host?.querySelectorAll('[data-dr-action]').forEach(button=>button.addEventListener('click',()=>handle(button.dataset.drAction,button.dataset.id)))}
  function errorView(){return `<section class="dr-error" role="alert"><h1>Data Responsibility</h1><p>We could not open the Data Responsibility workspace. Your saved project work has not been deleted.</p><div><button class="btn btn-primary" data-dr-action="retry" type="button">Try Again</button><button class="btn btn-secondary" data-dr-action="projects" type="button">Return to Projects</button><button class="btn btn-secondary" data-dr-action="projects" type="button">Select a Project</button><button class="btn btn-secondary" data-dr-action="start" type="button">Create a Data Plan Manually</button></div></section>`}
  function render(){const host=root.document?.getElementById('dataResponsibilityContent');if(!host)return false;readAll();host.innerHTML=loadError?errorView():(activeId&&getPlan()?wizard(getPlan()):overview());bind();host.querySelector('h1')?.focus?.();return true}
  function retry(){loadError=false;render()}

  root.ProjectDataResponsibilityExperience=Object.freeze({STATUSES,STEPS,TEMPLATES,DATA_CATEGORIES,SOURCE_STATUSES,CLASSIFICATIONS,SENSITIVE_CHECKS,CONSENT_STATUSES,ACCESS_ROLES,ACCESS_PERMISSIONS,LIFECYCLE,QUALITY_STATUSES,AI_FLOW,SERVICES,SERVICE_STATUSES,RISK_CATEGORIES,INCIDENT_FLOW,REVIEW_CHECKS,FINAL_FIELDS,DATA_MODELS,render,listPlans:readAll,getActivePlan:getPlan,retry,_test:{blankPlan,storageKey,reviewIssues,summaryCounts}});
  if(root.document?.getElementById('dataResponsibilityStudioView')?.classList.contains('active'))render();
})(typeof window!=='undefined'?window:globalThis);
